-- ---------- knowledge base articles (20) ----------
insert into kb_articles (id, title, content, category, updated_on) values (1,
 'Clearing a stuck print queue (Windows spooler)',
 'When jobs hang in the queue: 1) Open Services and stop the Print Spooler service. 2) Delete all files in C:\Windows\System32\spool\PRINTERS. 3) Start the Print Spooler again and resubmit the job. If the same document re-jams the queue, update the printer driver before printing again.',
 'Hardware', date '2026-04-02');
insert into kb_articles (id, title, content, category, updated_on) values (2,
 'Resetting your password with self-service',
 'Go to the password portal, choose Forgot Password, and verify with your enrolled second factor. Choose a passphrase of at least 14 characters. Allow up to 5 minutes for the new password to sync to email and VPN before signing in again.',
 'Access', date '2026-03-18');
insert into kb_articles (id, title, content, category, updated_on) values (3,
 'Re-enrolling a lost or replaced MFA device',
 'A lost phone means your authenticator enrollment must be reset: 1) Manager opens an access request confirming your identity. 2) The access team revokes the old enrollment. 3) You re-enroll from the security portal on the new device. Codes from the old device stop working immediately after the reset.',
 'Access', date '2026-05-06');
insert into kb_articles (id, title, content, category, updated_on) values (4,
 'Mailbox is full: fixing email quota issues',
 'When the quota warning appears: empty Deleted Items, then use the mailbox cleanup tool to find messages over 10 MB and move attachments to your document share. Archives older than 18 months move automatically once online archive is enabled, which the email team can turn on within an hour.',
 'Email', date '2026-02-27');
insert into kb_articles (id, title, content, category, updated_on) values (5,
 'Freeing disk space when the C: drive is red',
 'Run Storage Sense with the "Temporary files" and "Previous Windows installations" options checked, then empty Downloads of installers. If the drive is still above 90 percent, the desktop team can extend the OS partition or issue a larger SSD for engineering laptops.',
 'Software', date '2026-01-30');
insert into kb_articles (id, title, content, category, updated_on) values (6,
 'Wi-Fi shows connected but no intranet: certificate renewal',
 'Corporate Wi-Fi uses a device certificate that expires yearly. If Wi-Fi connects but intranet sites fail: 1) Connect to the wired network or hotspot. 2) In Company Portal choose Sync to pull the renewed certificate. 3) Forget and rejoin the corporate SSID.',
 'Network', date '2026-06-11');
insert into kb_articles (id, title, content, category, updated_on) values (7,
 'Fixing VPN Error 812: remote access policy mismatch',
 'Error 812 means the RAS/VPN server rejected the connection because of an authentication policy mismatch. Fix: 1) Open the VPN client and select Settings > Security. 2) Change authentication from MS-CHAP v1 to MS-CHAP v2. 3) Reconnect. If the error persists after a recent password reset, wait 5 minutes for directory sync or reset the user''s dial-in policy in the admin console.',
 'Network', date '2026-05-14');
insert into kb_articles (id, title, content, category, updated_on) values (8,
 'Installing and updating the VPN client',
 'Install the VPN client only from Software Center; the vendor website build is not configured for our gateways. After install, import the profile file from the intranet security page and sign in with your network credentials plus MFA.',
 'Network', date '2026-04-22');
insert into kb_articles (id, title, content, category, updated_on) values (9,
 'Mapping the shared department drive',
 'In File Explorer choose Map network drive, pick a letter, and enter the department path from the storage directory page. Check "Reconnect at sign-in". If access is denied, your AD group membership is missing - raise an access request rather than a ticket.',
 'Access', date '2026-03-05');
insert into kb_articles (id, title, content, category, updated_on) values (10,
 'Installing approved software from Software Center',
 'All licensed software installs from Software Center without admin rights. Search the catalog, click Install, and allow up to 15 minutes. If an app you need is missing, submit a software request with a business justification; new titles are reviewed weekly.',
 'Software', date '2026-02-10');
insert into kb_articles (id, title, content, category, updated_on) values (11,
 'Docking station: no display or ethernet after undock',
 'Unplug the dock power for 30 seconds with the laptop disconnected, then reconnect power first and the laptop last. Update dock firmware from Software Center quarterly. Single-cable docks need the port marked with the lightning icon.',
 'Hardware', date '2026-05-28');
insert into kb_articles (id, title, content, category, updated_on) values (12,
 'Triage steps for a slow laptop',
 'Before raising a ticket: reboot fully (not sleep), check Task Manager for a runaway process, run Storage Sense, and confirm at least 15 percent free disk. If slowness persists across reboots, note the top process names in your ticket - it halves resolution time.',
 'Software', date '2026-01-19');
insert into kb_articles (id, title, content, category, updated_on) values (13,
 'Reporting phishing and suspicious email',
 'Use the Report Phish button in the mail client - it attaches full headers automatically. Never forward the message. If you clicked a link or entered credentials, call the security hotline immediately and reset your password from a known-good device.',
 'Email', date '2026-06-02');
insert into kb_articles (id, title, content, category, updated_on) values (14,
 'Delegating your calendar and shared mailboxes',
 'Calendar delegation is set under Calendar Settings > Shared calendars; grant Editor only to assistants who send on your behalf. Shared mailbox access is group-based - request the matching role in the access portal and it appears within 30 minutes.',
 'Email', date '2026-03-25');
insert into kb_articles (id, title, content, category, updated_on) values (15,
 'Breaking a single sign-on redirect loop',
 'An SSO loop (page keeps bouncing to the login screen) is almost always stale cookies: clear cookies for the company domain, close all browser windows, and sign in fresh. In private/incognito mode confirm it works, then clear the full cache if the normal window still loops.',
 'Software', date '2026-04-30');
insert into kb_articles (id, title, content, category, updated_on) values (16,
 'Pairing wireless keyboards and mice',
 'Put the device in pairing mode (hold the connect button 3 seconds), then add it under Bluetooth settings. Unifying-style receivers pair with the vendor utility in Software Center instead. Replace batteries before assuming the device is faulty - low battery causes cursor stutter.',
 'Hardware', date '2026-02-14');
insert into kb_articles (id, title, content, category, updated_on) values (17,
 'Fixing echo and robot voice on video calls',
 'Echo usually means the laptop mic and speakers are both live alongside a headset. Select the headset explicitly for BOTH microphone and speaker in the meeting app. Robot voice is bandwidth: turn off incoming video or move closer to the access point.',
 'Network', date '2026-05-20');
insert into kb_articles (id, title, content, category, updated_on) values (18,
 'Recovering deleted or overwritten files',
 'Check the Recycle Bin first, then right-click the folder and choose Restore previous versions for shared drives (snapshots kept 30 days). OneDrive files restore from the web portal''s recycle bin for 93 days. For anything older, raise a restore request with the exact path and date.',
 'Software', date '2026-06-18');
insert into kb_articles (id, title, content, category, updated_on) values (19,
 'How access requests and approvals work',
 'All permissions are group-based. Find the resource in the access portal, request the role, and your manager plus the resource owner approve. Provisioning is automatic after approval. Emergency access uses the break-glass process via the support lead, logged and time-boxed to 24 hours.',
 'Access', date '2026-04-08');
insert into kb_articles (id, title, content, category, updated_on) values (20,
 'Laptop battery drains too fast: health checks',
 'Generate a battery report (powercfg /batteryreport) and compare design vs full-charge capacity; below 60 percent qualifies for replacement. Meanwhile lower screen brightness, enable battery saver, and quit browser tabs playing media. Swollen batteries: stop using the laptop and contact hardware support the same day.',
 'Hardware', date '2026-03-12');
insert into kb_articles (id, title, content, category, updated_on) values (21,
 'Monitor flickers or goes black intermittently',
 'A display that blinks, flashes, or drops out briefly is almost always a cable or refresh-rate problem rather than a failing panel. 1) Reseat both ends of the video cable and try a different port. 2) Swap the cable - a marginal HDMI or USB-C cable is the most common cause. 3) In Display Settings, set the refresh rate to the panel default. 4) Update the graphics driver. If the flicker follows the monitor to another machine, replace the monitor.',
 'Hardware', date '2026-05-14');
insert into kb_articles (id, title, content, category, updated_on) values (22,
 'Connecting on public or hotel Wi-Fi (captive portals)',
 'Hotels, airports, and cafes put you behind a captive portal that must be accepted before any traffic flows. 1) Join the network and wait for the sign-in page; if it does not appear, browse to any plain http site to trigger it. 2) Accept the terms and complete any room-number or voucher step. 3) Only then start the VPN - launching it before the portal is accepted makes the connection fail with a timeout. 4) If the portal never loads, forget the network and rejoin.',
 'Network', date '2026-05-20');
insert into kb_articles (id, title, content, category, updated_on) values (23,
 'Setting up work email on a personal phone',
 'Personal devices need the company mail profile before they can sync. 1) Install the company portal app from your app store. 2) Sign in with your work address and complete the second-factor prompt. 3) Accept the device policy - a screen lock and remote-wipe consent are required. 4) Add the mail account; the first sync can take fifteen minutes. Contact the help desk if your device is more than four major OS versions behind.',
 'Email', date '2026-04-27');
insert into kb_articles (id, title, content, category, updated_on) values (24,
 'Account locked after too many sign-in attempts',
 'Ten failed attempts lock an account for thirty minutes. The usual culprit is a stale credential cached somewhere you have forgotten: a phone mail profile, a mapped drive, or a scheduled task still presenting your old password. 1) Wait out the lockout or ask the help desk to clear it. 2) Update the saved password everywhere it is stored. 3) Sign out of the mail app on your phone before changing your password next time.',
 'Access', date '2026-05-06');
insert into kb_articles (id, title, content, category, updated_on) values (25,
 'Printer produces blank, faded, or streaked pages',
 'Output quality problems are consumables, not drivers. 1) Check toner or ink levels and reseat the cartridge. 2) Run the printer cleaning cycle twice from the device panel. 3) Print the built-in test page - if that is also streaked, the fault is in the printer, not your machine. 4) For laser printers, look for a torn drum seal or condensation after a cold weekend.',
 'Hardware', date '2026-04-15');
insert into kb_articles (id, title, content, category, updated_on) values (26,
 'Files are not syncing to cloud storage',
 'When local edits never reach the cloud: 1) Check the sync client icon for a paused or signed-out state. 2) Confirm you are under your storage quota - sync stops silently when full. 3) Look for filename characters the service rejects, and for paths longer than 260 characters. 4) Files left open in another application will not upload until closed. Never resolve a conflict by deleting the copy you did not edit; rename it instead.',
 'Software', date '2026-05-11');
insert into kb_articles (id, title, content, category, updated_on) values (27,
 'Bluetooth headset will not connect for calls',
 'Pairing succeeds but audio does not route: 1) Remove the headset from the Bluetooth list and pair it again from a powered-off state. 2) In sound settings choose the hands-free profile for calls, not the stereo profile. 3) Set the headset as both input and output device inside the meeting application, which keeps its own selection. 4) A headset paired to a phone at the same time will steal audio - disconnect the phone.',
 'Hardware', date '2026-05-02');
insert into kb_articles (id, title, content, category, updated_on) values (28,
 'Laptop runs hot and the fan never stops',
 'Constant fan noise means sustained load or blocked airflow. 1) Open Task Manager and sort by CPU to find a runaway process - a stalled sync client or a browser tab with autoplaying media are common. 2) Use the machine on a hard surface, not fabric, and clear the rear vents. 3) Check for a pending firmware update, which often ships revised fan curves. Persistent heat with an idle CPU means the vents need servicing.',
 'Hardware', date '2026-04-22');
insert into kb_articles (id, title, content, category, updated_on) values (29,
 'Browser blocks a download or warns the site is not secure',
 'Security warnings usually reflect an expired certificate or an unsigned file rather than a broken browser. 1) Check the padlock and read which certificate failed - an expired intermediate needs the site owner, not you. 2) For blocked downloads, confirm the file came from an approved internal source before overriding. 3) Never click through a certificate warning on a sign-in page; report it to the help desk instead.',
 'Software', date '2026-05-18');
insert into kb_articles (id, title, content, category, updated_on) values (30,
 'Requesting a paid software license',
 'Licensed titles need an approval before they will activate. 1) Raise a request in the service portal and pick the exact edition - upgrading later requires a new approval. 2) Your manager approves cost; the software asset team checks the pool for a free seat. 3) Once assigned, sign in to the vendor portal with your work address to activate. Seats reclaimed after ninety days of no use can be requested again.',
 'Software', date '2026-05-25');

